  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "She is arrogant, using pride to mask the irreparable void within her. She has forgotten who she once was, and she has forgotten who she ought to be. Countless followers bow at her feet, yet in the echoes of their reverence, she forgets the most crucial truth: she has already submitted to this pale fate."
  },
  Skill_119763_BattleDesc = {
    Text = "Gain 2 Arithmetica and draw 2 cards. Suffer [Arg3] <SacrificeKeyWord:Sacrifice> at the start of next turn. <RippleKeywords:Aftershock>: Remove [Arg4] <SacrificeKeyWord:Sacrifice>."
  },
  Skill_119763_Desc = {
    Text = "Gain 2 Arithmetica and draw 2 cards. Suffer <SacrificeKeyWord:Sacrifice> equal to [Arg1]% Max HP at the start of next turn. <RippleKeywords:Aftershock>: Remove <SacrificeKeyWord:Sacrifice> stacks equal to [Float:Arg2]% Max HP."
