  Skill_119763_EffectNameList = {
    Text = "Sacrifice Removal"
  },
  Skill_119763_Name = {
    Text = "Abyss Hymns"
  },
  Skill_119764_AwakerSkillBackgroundStory = {
    Text = "The origins of the ivory sculpture in Murphy's hands are subject to wide debate. Some claim it was recovered from the deep-sea ruins she guided, while others whisper it was birthed alongside the Divine Fetus from the beating heart within her own chest. Undeniably, this sculpture—a symbol of the intricate bond between her and the silent city of Lemuria resting beneath the lightless ocean—came into the Seafarers' view the day Murphy was declared the \"True Divine Mother.\" Thereafter, the faithful watched as Murphy wielded the ivory sculpture to break through stormy seas and cleave the ocean of blood. Absolute power transcends mere illusion; the knees of humanity can only bow before absolute strength."
  },
  Skill_119764_BattleDesc = {
    Text = "Gain <Block:[Block:Arg1]> Shield. Suffer [Arg7] <SacrificeKeyWord:Sacrifice> at the start of next turn. Inflict [Arg3] <plural value=\"[Arg3]\" singular=\"stack\" plural=\"stacks\"> of <DwmofeiKeywords:Birth Ritual> on all enemies. Deal <Damage:[Damage:Arg5]> DMG [Arg4] <plural value=\"[Arg4]\" singular=\"time\" plural=\"times\"> to the enemy with Highest HP, which enjoys an [Arg6]% <TentacleInjurieIconKeywords:Tentacle DMG> bonus."
  },
  Skill_119764_Desc = {
    Text = [[
Gain <Block:[Block:Arg1]> Shield. Suffer <SacrificeKeyWord:Sacrifice> equal to [Arg2]% Max HP at the start of next turn.
Inflict [Arg3] <plural value="[Arg3]" singular="stack" plural="stacks"> of <DwmofeiKeywords:Birth Ritual> on all enemies. Deal <Damage:[Damage:Arg5]> DMG [Arg4] <plural value="[Arg4]" singular="time" plural="times"> to the enemy with Highest HP, which enjoys an [Arg6]% <TentacleInjurieIconKeywords:Tentacle DMG> bonus.]]
