  Skill_132429_AwakerSkillBackgroundStory = {
    Text = "\nThe ocean is deep and serene, bearing the desire for life and the fear of death.\nYet there are those who choose to fill the ocean with laughter and mischief—when Aurita extends such an invitation, the thought of \"why not have some fun with her\" always comes to mind, allowing simple joy to fill the heart."
  },
  Skill_132429_Desc_0 = {
    Text = "Deal <Damage:[Damage:Arg1]> DMG. Expend up to 10 \"Gland Division\" from the Draw Pile and Discard Pile, each provides 1 more DMG instance. Place 2 \"Gland Division\" into hand. Increase Aurita's DMG output in this battle by [Arg2]."
  },
  Skill_132429_Desc_2 = {
    Text = "Deal <Damage:[Damage:Arg1]> <PunctureDamagewords:Pierce DMG>. Consume up to 10 \"Gland Division\" cards from the Draw Pile and Discard Pile, each causing an additional instance of DMG. Place 2 \"Gland Division\" cards into hand. Increase the DMG caused by Aurita in this battle by [Arg2]."
  },
