  Skill_133348_Name_1 = {
    Text = "Muddied Fairy Tale"
  },
  Skill_133365_AwakerSkillBackgroundStory = {
    Text = "She had heard the sound of threads snapping countless times.\nA reunion that never happened. A confession never spoken. A child never born.\nA piece of music never brought to the world. A war never won. A civilization that never survived.\nThreads weave. Threads snap. Threads converge back into that vast web.\nThe deity of fate has long known—nothing ever truly perishes, nothing ever truly existed."
  },
  Skill_133365_Desc_0 = {
