  Skill_144438_Desc_1 = {
    Text = "<PVPWeaponKeywords:Wheel of Destiny>: When an ally dies, gain <Energy:[Energy:Arg1]> Aliemus. When an ally is revived, they gain <Energy:[Energy:Arg2]> Aliemus. This Aliemus gain only triggers if the target's Aliemus is not full, up to [Arg8] times. Destroy this Wheel of Destiny once this limit is reached."
  },
