  Skill_144491_BattleDesc_0 = {
    Text = "Caraboo gains <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: After using \"Crimson Furnace\", the next <DerivativeCardKeywords_160:\"Miracle Blessing\"> costs -3 Arithmetica, and each <FaxianKeywords:Discover> option is upgraded to a set that contains 1 more <DerivativeCardKeywords_152:\"Blessing\"> card. Choose 1 set to shuffle into your Draw Pile."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo gains <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: After using \"Crimson Furnace\", the next <DerivativeCardKeywords_160:\"Miracle Blessing\"> costs -3 Arithmetica, and each <FaxianKeywords:Discover> option is upgraded to a set that contains 2 more <DerivativeCardKeywords_152:\"Blessing\"> cards. Choose 1 set to shuffle into your Draw Pile. After playing a \"Blessing\" card, Embryo Fusion +10. This fusion effect increases based on your lost HP, up to +100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo gains [Arg2]% Base Aliemus. <ExaltIconKeywords:Rouse>: After using \"Crimson Furnace\", the next <DerivativeCardKeywords_160:\"Miracle Blessing\"> costs -3 Arithmetica, and each <FaxianKeywords:Discover> option is upgraded to a set that contains 1 more <DerivativeCardKeywords_152:\"Blessing\"> card. Choose 1 set to shuffle into your Draw Pile."
