  Skill_145676_AwakerSkillBackgroundStory = {
    Text = "When each knight was knighted and took their oath, the weapon at their side was likewise gilded with glory.\nYet the first silver lance that had belonged to him — the one bestowed with a sacred mission — had long since melted away in the dying embers of battle.\nStill, since he was already a man burdened with sin, he thought he might as well let this sinful, murky black become his new weapon. That way, he figured, even if more blood were to stain it, it would no longer bring shame upon those he once knew."
  },
  Skill_145676_BattleDesc_0 = {
    Text = "Deal <Damage:[Damage:Arg1]> DMG, benefits from [Arg2]% Power bonus, gain 1 stack of <KuangNu:Dark Surge>."
