  },
  Skill_145677_AwakerSkillBackgroundStory = {
    Text = "Once, the boy had tried to tear that wicked black sludge away from himself — yet no matter what he did, whether ripping at it with his hands, cutting it with a blade, or striking it with a blunt weapon... the formless nightmare refused to be dispelled, and only grew more brazen.\nIn the end, he finally admitted that he and It had long since completely merged into one, inseparable from each other.\nIt had become his shadow."
  },
  Skill_145677_BattleDesc_0 = {
    Text = "Vow-Breaker·Ogier gains <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: The first time Vow-Breaker·Ogier deals DMG with \"Sin-Stained Spearpoint\" each round, apply equal <Corrosion:Corrosion>. Shield Boost of \"Defense\" increases by 50%, draw 1 card."
  },
  Skill_145677_BattleDesc_15 = {
    Text = "Vow-Breaker·Ogier gains <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: The first time Vow-Breaker·Ogier deals DMG with \"Sin-Stained Spearpoint\" each round, apply equal <Corrosion:Corrosion>. Base DMG of \"Sin-Stained Spearpoint\" increases by 100%, additionally benefits from 200% Power bonus. Shield Boost of \"Defense\" increases by 100%, draw 1 card."
  },
  Skill_145677_Desc_0 = {
