  Skill_146016_AwakerSkillBackgroundStory = {
    Text = [[
The deity tore her spirit from her flesh, deeming this the final judgment upon chaos.
Yet the hollow soul never ceased its pursuit, and the severed power never truly faded.
When bone armor once again clad her form, and the pulse of Leviathan resonated with her will, every shackle shattered in an instant.
Deep within the cosmos, flesh and soul fused anew. The Beast of Chaos was whole once more.
And this starry sea shall welcome her return.]]
  },
  Skill_146016_BattleDesc_0 = {
    Text = "Lotan: Cetarchon gains <Energy:[Energy:Arg1]> Base Aliemus. <ExaltIconKeywords:Rouse>: Lotan: Cetarchon's Command Cards deal +1 instance of DMG.\nAt turn start, if <DerivativeCardKeywords_153:\"Great Blade: Whalefall\"> is in hand: \nThe first <DerivativeCardKeywords_154:\"Deadly Duel\"> played that turn empowers your next \"Mundus Severance\"—for each 1 Aliemus it steals, \"Mundus Severance\" deals +1% Final DMG (max 90%)."
  },
  Skill_146016_BattleDesc_15 = {
    Text = "Lotan: Cetarchon gains <Energy:[Energy:Arg1]> Base Aliemus. <ExaltIconKeywords:Rouse>: Lotan: Cetarchon's Command Cards deal +1 instance of DMG.\nLotan: Cetarchon receives +50% Aliemus through <DerivativeCardKeywords_154:\"Deadly Duel\">. At turn start, if <DerivativeCardKeywords_153:\"Great Blade: Whalefall\"> is in hand: \nThe first <DerivativeCardKeywords_154:\"Deadly Duel\"> played that turn empowers your next \"Mundus Severance\"—for each 1 Aliemus it steals, \"Mundus Severance\" deals +1.5% Final DMG (max 135%)."
