  Skill_4152_AwakerSkillBackgroundStory = {
    Text = "Bloodshed, corpses, or piercing pain—none of it matters.\nThese are insignificant sacrifices for the return of the divine kingdom.\nShe only regrets not being the chosen one, not the girl imprisoned in the cage."
