  Skill_70286_Name_1 = {
    Text = "Blue Stone Throne"
  },
  Skill_70299_AwakerSkillBackgroundStory = {
    Text = [[
The destination she sought all her life now waits, a pitch-black door whispering promises. 
Before opening it, she imagined 372 possibilities of truths. 
After, only the 373rd remained, the one she dreaded. 
No choice left. She falls. 
What terrible luck... for her, and for the entire world.]]
  },
  Skill_70299_BattleDesc = {
    Text = "Other Awakeners gain <Energy:[Energy:Arg1]> Aliemus, inflict [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"stack\" plural=\"stacks\"> of <IntoxicationIconKeywords:Poison> on all enemies, and Temporary DMG Amplification +[Arg3]%."
  },
  Skill_70299_Desc = {
    Text = "Other Awakeners gain <Energy:[Energy:Arg1]> Aliemus, inflict [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"stack\" plural=\"stacks\"> of <IntoxicationIconKeywords:Poison> on all enemies, and Temporary DMG Amplification +[Arg3]%. \"Finale Form\": Draw 3 additional cards, obtain 3 Arithmetica, trigger 50% of <IntoxicationIconKeywords:Poison> on all enemies, and increase \"Doll: Inferno\"'s Base Aliemus by 50, up to 3 times."
  },
  Skill_70299_EffectNameList = {
    Text = "Aliemus,Poison,DMG Amp."
  },
  Skill_70299_Name = {
    Text = "Terminal of Truth and Abyss"
  },
  Skill_70299_OverLimitUtlSkillDesc = {
    Text = "Other Awakeners gain <Energy:[Energy:Arg4]> Aliemus, inflict [Poison:Arg2] <plural value=\"[Poison:Arg2]\" singular=\"stack\" plural=\"stacks\"> of <IntoxicationIconKeywords:Poison> on all enemies, Temporary DMG Amplification +[Arg3]%, and increase all Awakeners' <IntoxicationIconKeywords:Poison>, <RetaliateIconKeywords:Counter>, and Base DMG by 10%. In Boss Battles, obtain an additional stack of \"Finale\"."
  },
  Skill_70299_PropertyNameList = {
    Text = "$GrowValue1,ATK*GrowValue2,$GrowValue3%"
  },
  Skill_70300_AwakerSkillBackgroundStory = {
    Text = "The crimson capsule swells beneath its mechanical carapace as the brass resonator hums, spinning a honeycomb of defenses. \nMycelial pulses split the air; acid mist carves warnings into flesh. Memory-shearing beams glow hot—cross the boundary, and your twitching remains will end up in a petri dish."
  },
  Skill_70300_BattleDesc = {
    Text = "Gain <Block:[Block:Arg1]> Shield. Gain <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_70300_Desc = {
    Text = "Gain <Block:[Block:Arg1]> Shield. \"Doll: Inferno\" obtains <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_70300_EffectNameList = {
    Text = "Shield,Aliemus"
  },
  Skill_70300_Name = {Text = "Defense"},
  Skill_70300_PropertyNameList = {
    Text = "DEF*GrowValue1,$GrowValue2"
  },
  Skill_70301_AwakerSkillBackgroundStory = {
    Text = [[
The pincers are relics of her past, of her bloodline. A power she never relinquished. 
When they sink into an enemy's chest, her smile blooms like a wound... what does it mean? Only the dead could say, and they don't speak]]
  },
  Skill_70301_BattleDesc = {
    Text = "Deal <Damage:[Damage:Arg1]> DMG. Gain <Energy:[Energy:Arg2]> Aliemus."
  },
  Skill_70301_Desc = {
