  },
  Skill_70302_AwakerSkillBackgroundStory = {
    Text = [[
She sacrificed herself, buying passage to the hidden truth. 
When she pulled her hand back, her soul dripped like melted wax.]]
  },
  Skill_70302_BattleDesc_0 = {
    Text = "Doll: Inferno gains <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: At turn end, recover <Heal:[Heal:Arg2]> HP and gain <Energy:[Energy:Arg4]> Aliemus. \"Finale Form\": No longer recover HP; instead trigger [Arg3]% <IntoxicationIconKeywords:Poison> on all enemies."
  },
  Skill_70302_BattleDesc_15 = {
    Text = "Doll: Inferno gains <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: For each stack of \"Finale,\" DMG Amplification +8%. \"Illusion's End\" grants all Awakeners 30% Base Aliemus. At turn end, recover <Heal:[Heal:Arg2]> HP and gain <Energy:[Energy:Arg4]> Aliemus. \"Finale Form\": No longer recover HP, instead trigger [Arg3]% <IntoxicationIconKeywords:Poison> on all enemies."
  },
  Skill_70302_Desc_0 = {
    Text = "Doll: Inferno gains <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: At turn end, recover <Heal:[Heal:Arg2]> HP and gain Aliemus equal to its own Aliemus Regen. \"Finale Form\": No longer recover HP; instead, trigger [Arg3]% <IntoxicationIconKeywords:Poison> on all enemies."
  },
  Skill_70302_Desc_15 = {
    Text = "Doll: Inferno gains <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Rouse>: For each stack of \"Finale,\" DMG Amplification +8%. \"Illusion's End\" grants all Awakeners 30% Base Aliemus. At turn end, recover <Heal:[Heal:Arg2]> HP and gain Aliemus equal to the Aliemus Regen. \"Finale Form\": No longer recover HP, instead trigger [Arg3]% <IntoxicationIconKeywords:Poison> on all enemies."
  },
